#!/usr/bin/env python3
"""
EMI pre-analysis: differential-mode spectrum of the DC-link ripple current, common-mode current
from the switching-node dv/dt through parasitic capacitances, required filter attenuation
against CISPR 11 class A (group 1) conducted limits, and a two-stage filter proposal with its
calculated insertion loss.  No measurement is implied.
"""
import os, sys, json, math
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE); sys.path.insert(0, ROOT)
from dabtools.dab import dab_model as M
import matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
V = json.load(open(os.path.join(ROOT, "04_Design_Calculations", "design_values.json")))
L, n, fs = V["L"], V["spec"]["n"], V["spec"]["fs"]
pt = M.DABPoint(800, 400, n, L, fs, V["phi_nom"], N=8192)
# DM: bridge input current spectrum (HV port) into the link capacitor; the source impedance is the LISN (50 Ohm || 50 uH per line)
i_br = pt.i * np.sign(pt.v1); i_ac = i_br - i_br.mean()
spec = np.abs(np.fft.rfft(i_ac)) / len(i_ac) * 2
f = np.arange(len(spec)) * fs
C1 = V["dclink"]["C1"]; ESL = 20e-9; ESR = V["dclink"]["ESR1"]
Zc = np.abs(ESR + 1j * (2 * math.pi * f * ESL - 1 / (2 * math.pi * np.maximum(f, 1) * C1)))
Zlisn = 100.0                                   # differential 2 x 50 Ohm
v_dm = spec * (Zc * Zlisn / (Zc + Zlisn))       # voltage across the LISN without filter (V)
dm_dbuv = 20 * np.log10(np.maximum(v_dm, 1e-9) / 1e-6)
# CM: dv/dt of the four switching nodes (two per bridge) through Cp to the heatsink (PE)
dvdt = 20e9; Cp = 50e-12 * 2                     # per TO-247 to heatsink through a pad, 2 nodes per bridge
tr = 800 / dvdt
# trapezoid spectrum envelope of the CM current pulses: I_cm = Cp * dv/dt for tr, 4 pulses per period
Icm_pk = Cp * dvdt
fk = np.logspace(5, 7.5, 300)
env = 2 * Icm_pk * tr * fs * np.minimum(1, 1 / (math.pi * fk * tr)) * 4   # harmonic amplitude envelope (A)
v_cm = env * 25.0                                # CM LISN impedance 25 Ohm
cm_dbuv = 20 * np.log10(v_cm / 1e-6)
# CISPR 11 class A group 1, conducted, quasi-peak (dBuV): 150-500 kHz 79, 0.5-30 MHz 73  (average: 66 / 60)
def limit_qp(fx): return np.where(fx < 500e3, 79.0, 73.0)
req_dm = np.maximum(0, dm_dbuv[(f >= 150e3) & (f <= 30e6)] - limit_qp(f[(f >= 150e3) & (f <= 30e6)]))
req_cm = np.maximum(0, cm_dbuv - limit_qp(fk))
att_needed_dm = float(req_dm.max()) + 6; att_needed_cm = float(req_cm.max()) + 6
# filter: DM: L_dm 10 uH + C_x 2.2 uF (two stages); CM: 2 x 3 mH choke + 4 x 4.7 nF Y
def lc_att(fx, Lf, Cf): return 20 * np.log10(np.maximum(1, (2 * math.pi * fx) ** 2 * Lf * Cf))
dm_filter = 2 * lc_att(fk, 10e-6, 2.2e-6); cm_filter = 2 * lc_att(fk, 3e-3, 2 * 4.7e-9)
fig, ax = plt.subplots(1, 2, figsize=(11, 3.8))
m = (f >= 100e3) & (f <= 30e6)
ax[0].semilogx(f[m], dm_dbuv[m], ".", ms=3, label="DM, no filter (model)"); ax[0].semilogx(fk, limit_qp(fk), "r--", label="CISPR 11 A QP")
ax[0].semilogx(fk, np.interp(fk, f[m], dm_dbuv[m]) - dm_filter, "g-", label="DM with 2-stage LC"); ax[0].set_xlabel("Hz"); ax[0].set_ylabel("dBuV"); ax[0].legend(fontsize=8); ax[0].grid(alpha=0.3); ax[0].set_ylim(0, 160)
ax[1].semilogx(fk, cm_dbuv, label="CM envelope, no filter (model)"); ax[1].semilogx(fk, limit_qp(fk), "r--", label="CISPR 11 A QP"); ax[1].semilogx(fk, cm_dbuv - cm_filter, "g-", label="CM with 2 x (3 mH + 2 x 4.7 nF)")
ax[1].set_xlabel("Hz"); ax[1].set_ylabel("dBuV"); ax[1].legend(fontsize=8); ax[1].grid(alpha=0.3); ax[1].set_ylim(0, 160)
fig.tight_layout(); fig.savefig(os.path.join(HERE, "img", "emi_estimate.png"), dpi=130)
R = []; w = R.append
w("# 14 - EMI / EMC engineering\n\n_Generated by `emi_analysis.py`; analytical pre-estimate, not a measurement._\n")
w("## 1. Applicable standards (installation: industrial cabinet, DC ports)\n* Emission: CISPR 11 / EN 55011 class A group 1 (industrial), conducted 150 kHz - 30 MHz on the DC ports (measured with a DC LISN per CISPR 16-1-2), radiated 30 MHz - 1 GHz at 10 m; IEC 61800-3 category C3 by analogy for a converter inside a drive-like system.\n* Immunity: IEC 61000-6-2 (ESD 4/8 kV, RF 10 V/m, EFT 2 kV on power ports, surge 1 kV/2 kV, conducted RF 10 V).\n* Compliance is demonstrated only by test in an accredited lab (20_Experimental_Test_Plan, EMI pre-compliance).\n")
w(f"## 2. Noise sources\n* Differential mode: the HV-bridge input current is pulsating at 2 fs with {np.sqrt(np.mean(i_ac**2)):.1f} A rms; the link capacitors (4 x 20 uF, ESR {ESR*1e3:.0f} mOhm, ESL {ESL*1e9:.0f} nH) absorb it but the residual voltage across a 100 Ohm LISN reaches {dm_dbuv[m].max():.0f} dBuV at {f[m][np.argmax(dm_dbuv[m])]/1e3:.0f} kHz without a filter.\n"
  f"* Common mode: four switching nodes with ~{dvdt/1e9:.0f} V/ns edges drive {Icm_pk:.1f} A peak pulses through ~{Cp*1e12:.0f} pF per node to the earthed heatsink; the transformer interwinding capacitance ({V['transformer']['C_iw']*1e12:.0f} pF) couples HV-side CM noise to the LV port. Envelope estimate: {cm_dbuv.max():.0f} dBuV at 150 kHz.\n")
w(f"## 3. Required attenuation and filter proposal\nRequired (with 6 dB margin): DM {att_needed_dm:.0f} dB, CM {att_needed_cm:.0f} dB in the 150 kHz - 2 MHz range.\n\n| stage | DM | CM |\n|---|---|---|\n| 1 | 10 uH (powder core) + 2.2 uF X2 (1000 V film) | 3 mH nanocrystalline CM choke (20 A) + 2 x 4.7 nF Y1 to PE |\n| 2 | 10 uH + 2.2 uF | 3 mH + 2 x 4.7 nF |\n\nCalculated insertion loss at 150 kHz: DM {np.interp(150e3, fk, dm_filter):.0f} dB, CM {np.interp(150e3, fk, cm_filter):.0f} dB. The Y-capacitor leakage current at 100 kHz is driven by the converter, not the mains, so the touch-current limit does not apply to the DC ports, but the PE current must be bonded (SAF-05).\n")
w("![emi](img/emi_estimate.png)\n")
w("## 4. Layout and construction measures (implemented in 08_KiCad_PCB)\n* Switching loops: each half-bridge leg has its 2220 MLCC decoupling within 10 mm of the drain/source pins; the DC-link film capacitors feed the planes.\n* The transformer and inductor are the only components crossing the HV/LV barrier; a shield foil (connected to the HV link midpoint) between primary and secondary is specified as an option in 06_Magnetics to reduce C_iw coupling.\n* Gate loops are referenced to the Kelvin source; the drivers sit within 15 mm of the gates; the isolated driver bias modules have < 10 pF isolation capacitance each (to limit dv/dt current into the control ground).\n* Control ground is a single plane under the DSP, connected to PE at one point (star) through the mounting hole near the connector; sensing uses isolated amplifiers (AMC1311) so no HV reference enters the control ground.\n* Heatsinks bonded to PE with short straps; Y capacitors from each DC rail to PE at the port connectors (the first CM filter element).\n")
w("## 5. Pre-compliance test plan (summary, details in 20)\n1. Conducted emissions on both DC ports with DC LISNs, 150 kHz - 30 MHz, QP and AV, at 25/50/100 % load, both power directions.\n2. Radiated emissions pre-scan 30 MHz - 1 GHz with a near-field probe set and a 3 m semi-anechoic scan if available.\n3. Immunity: ESD on connectors and enclosure, EFT on DC ports and CAN, surge on DC ports, conducted RF on cables - functional criterion: no fault trip, < 1 % regulation disturbance.\n")
open(os.path.join(HERE, "emi_report.md"), "w").write("\n".join(R) + "\n")
print("\n".join(R)[:1500])
